import { CircleAlert, CircleCheck } from 'lucide-react'
import * as React from 'react'
import { useId } from 'react'

import { cx } from '~/lib/cx'
import { Label } from './label'
import styles from './input.module.scss'

export type InputSize = 'sm' | 'md' | 'lg'

const SIZE: Record<InputSize, string> = {
  sm: styles.sm,
  md: '',
  lg: styles.lg,
}

export interface InputProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'size'> {
  label?: string
  hint?: string
  error?: string
  success?: string
  size?: InputSize
  /** Rendered before the control — text or an icon. */
  leading?: React.ReactNode
  /** Rendered after the control — text or an icon. */
  trailing?: React.ReactNode
  /** Legacy aliases used by the Tailwind kit. */
  leadingNode?: React.ReactNode
  trailingNode?: React.ReactNode
  /** Visual treatment. `outlined` uses a tighter border and page background. */
  appearance?: 'default' | 'outlined' | 'filled'
  /** Class for the outer field wrapper. */
  wrapClassName?: string
}

export const Input = React.forwardRef<HTMLInputElement, InputProps>(
  function Input(
    {
      label,
      hint,
      error,
      success,
      size = 'md',
      leading,
      trailing,
      leadingNode,
      trailingNode,
      appearance = 'default',
      wrapClassName,
      id: idProp,
      className,
      required,
      disabled,
      ...props
    },
    ref,
  ) {
    const generatedId = useId()
    const id = idProp ?? generatedId
    const lead = leadingNode ?? leading
    const trail = trailingNode ?? trailing

    const hasError = Boolean(error)
    const hasSuccess = Boolean(success) && !hasError
    const describedBy =
      [
        hint ? `${id}-hint` : null,
        hasError ? `${id}-error` : null,
        hasSuccess ? `${id}-success` : null,
      ]
        .filter(Boolean)
        .join(' ') || undefined

    return (
      <div className={cx(styles.field, wrapClassName)}>
        {label ? (
          <Label
            htmlFor={id}
            required={required}
            hint={hint}
            hintId={`${id}-hint`}
          >
            {label}
          </Label>
        ) : null}

        <div
          className={cx(
            styles.shell,
            SIZE[size],
            appearance === 'outlined' && styles.outlined,
            appearance === 'filled' && styles.filled,
            hasError ? styles.invalid : hasSuccess ? styles.valid : undefined,
            disabled && styles.disabled,
          )}
        >
          {lead ? <span className={styles.affix}>{lead}</span> : null}

          <input
            {...props}
            ref={ref}
            id={id}
            required={required}
            disabled={disabled}
            aria-invalid={hasError || undefined}
            aria-describedby={describedBy}
            className={cx(styles.control, className)}
          />

          {hasError ? (
            <span className={cx(styles.status, styles.statusError)}>
              <CircleAlert aria-hidden />
            </span>
          ) : hasSuccess ? (
            <span className={cx(styles.status, styles.statusSuccess)}>
              <CircleCheck aria-hidden />
            </span>
          ) : null}

          {trail ? <span className={styles.affix}>{trail}</span> : null}
        </div>

        {hasError ? (
          <p id={`${id}-error`} role="alert" className={cx(styles.message, styles.errorText)}>
            {error}
          </p>
        ) : hasSuccess ? (
          <p id={`${id}-success`} className={cx(styles.message, styles.successText)}>
            {success}
          </p>
        ) : null}
      </div>
    )
  },
)

/** Bare control for composed groups, toolbars and custom shells. */
export const BareInput = React.forwardRef<
  HTMLInputElement,
  React.InputHTMLAttributes<HTMLInputElement>
>(function BareInput({ className, ...props }, ref) {
  return <input ref={ref} className={cx(styles.bare, className)} {...props} />
})

/** Alias matching the legacy Tailwind kit. */
export { Input as InputField }

@use 'styles' as vz;

.field {
  display: flex;
  flex-direction: column;
  gap: vz.space(1);
  min-width: 0;
}

.shell {
  --input-height: #{vz.space(10)};
  --input-radius: #{vz.radius('lg')};
  --input-px: #{vz.space(3)};

  position: relative;
  display: flex;
  align-items: center;
  gap: vz.space(2);
  height: var(--input-height);
  padding-inline: var(--input-px);
  border: 1px solid vz.color('border');
  border-radius: var(--input-radius);
  background: vz.color('card');
  color: vz.color('foreground');
  transition:
    border-color vz.duration('base') vz.ease('out'),
    box-shadow vz.duration('base') vz.ease('out'),
    background-color vz.duration('base') vz.ease('out');

  &:focus-within {
    border-color: vz.color('primary');
    box-shadow: 0 0 0 3px vz.color('primary', 0.18);
  }
}

.sm {
  --input-height: #{vz.space(8)};
  --input-radius: #{vz.radius('md')};
  --input-px: #{vz.space(2.5)};
}

.lg {
  --input-height: #{vz.space(12)};
  --input-radius: #{vz.radius('xl')};
  --input-px: #{vz.space(4)};
}

.outlined {
  --input-radius: #{vz.radius('sm')};

  background: vz.color('background');

  &:focus-within {
    border-color: vz.color('input');
    box-shadow: none;
    outline: 2px solid vz.color('ring', 0.6);
    outline-offset: 2px;
  }
}

.filled {
  border-color: transparent;
  background: vz.color('muted');

  &:focus-within {
    border-color: vz.color('primary');
    background: vz.color('card');
  }
}

.bare {
  width: 100%;
  min-height: 2.5rem;
  padding: vz.space(2) vz.space(3);
  border: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: vz.font-size('sm');
  outline: none;

  @include vz.placeholder {
    color: vz.color('muted-foreground');
  }
}

.invalid {
  border-color: vz.color('destructive');

  &:focus-within {
    border-color: vz.color('destructive');
    box-shadow: 0 0 0 3px vz.color('destructive', 0.18);
  }
}

.valid {
  border-color: vz.color('success');

  &:focus-within {
    border-color: vz.color('success');
    box-shadow: 0 0 0 3px vz.color('success', 0.18);
  }
}

.disabled {
  background: vz.color('muted');
  opacity: 0.6;
  pointer-events: none;
}

.control {
  flex: 1;
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font-size: vz.font-size('sm');
  line-height: 1.25;
  caret-color: vz.color('primary');
  outline: none;

  @include vz.placeholder {
    color: vz.color('muted-foreground');
  }

  // Keep autofill from painting the control yellow.
  &:autofill,
  &:-webkit-autofill {
    -webkit-text-fill-color: vz.color('foreground');
    box-shadow: inset 0 0 0 100px vz.color('card');
  }
}

.affix {
  display: inline-flex;
  flex: none;
  align-items: center;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');

  svg {
    @include vz.icon(4);
  }
}

.status {
  display: inline-flex;
  flex: none;
  align-items: center;
  animation: vz-status-in 180ms vz.ease('spring') both;

  svg {
    @include vz.icon(4);
  }

  @include vz.motion-reduce {
    animation: none;
  }
}

@keyframes vz-status-in {
  from {
    opacity: 0;
    transform: scale(0.6);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

.status-error {
  color: vz.color('destructive');
}

.status-success {
  color: vz.color('success');
}

.message {
  margin: 0;
  font-size: vz.font-size('xs');
}

.error-text {
  color: vz.color('destructive');
}

.success-text {
  color: vz.color('success');
}
